using StockFeed.Contracts;
using StockFeed.Slices.StockFeed;
using StockFeed.Views;
using Marten;
using Shouldly;
using Xunit;

namespace StockFeed.IntegrationTests.Slices.StockFeed;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation. Pattern: view. Status: ready.
/// LIVE, so every test here must pass.
///
/// A View is specified as GIVEN a set of events, THEN the read model shows this — no WHEN, because a read model
/// only ever reads events that already exist and there is no command to be the middle step.
/// </summary>
public sealed class StockLevelsTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static Guid Stream => TranslateStockNoticeState.StreamKey(SeedData.ProductId);

    private async Task<StockLevels?> Level()
    {
        await using var session = Store.QuerySession();
        return await session.LoadAsync<StockLevels>(Stream);
    }

    // the level we accepted is what the system reads
    //   GIVEN StockNoticed, StockLevelSet
    //   THEN  StockLevels
    [Fact]
    public async Task TheLevelWeAcceptedIsWhatTheSystemReads()
    {
        await Given(Stream, SeedData.LevelSet());

        var level = await Level();

        level.ShouldNotBeNull();
        level.ProductId.ShouldBe(SeedData.ProductId);
        level.OnHand.ShouldBe(SeedData.Quantity);
        level.Sequence.ShouldBe(SeedData.Sequence);
        level.SetAt.ShouldBe(SeedData.SeededAt);
    }

    // a notice we have not accepted does not reach the read side
    //   GIVEN StockNoticed
    //   THEN  StockLevels
    [Fact]
    public async Task ANoticeWeHaveNotAcceptedDoesNotReachTheReadSide()
    {
        // THE GIVEN IS A NOTICE AND NOTHING ELSE, and there is nothing to append for it — which is now the
        // strongest possible form of this assertion rather than a weaker one.
        //
        // In the first version of this folder the notice WAS appended, so this test proved the projection ignored
        // an event that was sitting right there in the same stream: a real and breakable claim, and one mutation
        // killed it. Now the claim is structural. A projection cannot fold StockNoticed even by mistake, because
        // StockNoticed is never in the store — the impossible-to-get-wrong version of the same guarantee.
        //
        // The test is kept even though it can no longer fail from a fold mistake, because it is what the MODEL
        // specifies and it would fail loudly the moment somebody decides to start recording arrivals. That is
        // exactly the change it should be standing guard over.
        (await Level()).ShouldBeNull();
    }

    /// <summary>
    /// NOT FROM THE MODEL. A refused notice must leave the read side on the level we accepted — the refusal has to
    /// be invisible downstream, not merely logged.
    /// </summary>
    [Fact]
    public async Task ARefusedNoticeLeavesTheReadSideOnTheLevelWeAccepted()
    {
        await Given(Stream, SeedData.LevelSet());

        var level = await Level();

        level.ShouldNotBeNull();
        level.OnHand.ShouldBe(SeedData.Quantity);
        level.Sequence.ShouldBe(SeedData.Sequence);
    }
}
